{
  "title": "Detect Service Account Login from Unauthorized Host",
  "id": "f5b3e9c2-8a4d-4c1f-9d2e-1a2b3c4d5e6f",
  "status": "experimental",
  "description": "Detect authentication events where a known service account logs in from a host IP not in its allowed list.",
  "author": "SOC Analyst",
  "logsource": {
    "product": "windows",
    "service": "security"
  },
  "detection": {
    "selection": {
      "EventID": 4624,
      "AccountName": "svc_deploy_prod"
    },
    "condition": "selection and not AuthorizedHost",
    "AuthorizedHost": {
      "SourceIP|contains": ["10.0.6.10"]
    }
  },
  "falsepositives": ["Legitimate admin activity from new host"],
  "level": "high"
}
